INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (27, 44, "人助けが大好き！　前向き格闘娘", 100101, "人助け、応援", "ヒヨリ", 8, 2, 16, "A", 0, "獣人族", "トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "東山奈央", 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 47, "戦闘のサポートが得意な、心優しい少女", 100201, "料理、人間観察", "ユイ", 4, 2, 17, "O", 0, "ヒューマン", "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "種田梨沙", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 46, "クールで何事にも真っ直ぐな剣士", 100301, "読書、乗馬、お茶", "レイ", 1, 2, 18, "B", 0, "魔族", "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "早見沙織", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 27, "探検好きのイタズラっ子", 100401, "いたずら、探検", "ミソギ", 8, 5, 9, "O", 0, "ヒューマン", "リトルリリカル", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "諸星すみれ", 128);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, 40, "ヒーローに憧れる騎士見習いの少女", 100501, "ヒーローごっこ", "マツリ", 11, 8, 12, "O", 0, "獣人族", "王宮騎士団（NIGHTMARE）", "？？？", "下田麻美", 146);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 42, "甘え上手なみんなの人気者", 100601, "サックス", "アカリ", 11, 7, 13, "O", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "浅倉杏美", 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (23, 32, "プリン大好きゴースト娘", 100701, "プリンを食べること", "ミヤコ", 1, 7, 14, "B", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "雨宮天", 130);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 40, "ボクは誰よりも美しい", 100801, "鏡で自分を見ること", "ユキ", 10, 15, 14, "AB", 0, "エルフ", "ヴァイスフリューゲル　ランドソル支部", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "大空直美", 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 45, "前世を信じる中二病患者、「疾風の冥姫」", 100901, "小説執筆", "アンナ", 7, 13, 17, "A", 0, "魔族", "トワイライトキャラバン", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "髙野麻美", 159);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 42, "マホマホ王国のプリンセス", 101001, "空想、ぬいぐるみ集め", "マホ", 9, 10, 16, "O", 0, "獣人族", "自警団（カォン）", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "内田真礼", 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, 44, "人懐っこくてマシンガントークな妹系少女", 101101, "お裁縫", "リノ", 8, 3, 15, "A", 0, "ヒューマン", "ラビリンス", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "阿澄佳奈", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 46, "みんなのために超能力を使う眠り姫", 101201, "妹と遊ぶこと、二度寝、昼寝、早寝", "ハツネ", 12, 6, 17, "A", 0, "エルフ", "フォレスティエ", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "大橋彩香", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (21, 55, "オタク全開な魔法少女", 101301, "読書、魔法", "ナナカ", 8, 13, 18, "O", 0, "魔族", "トワイライトキャラバン", "", "佳村はるか", 166);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 41, "頭脳明晰な美少女名探偵", 101401, "読書、推理", "カスミ", 11, 10, 15, "AB", 0, "獣人族", "自警団（カォン）", "test", "水瀬いのり", 152);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 54, "母性溢れる優しいみんなの「ミサト先生」", 101501, "絵本作り", "ミサト", 9, 6, 21, "O", 0, "エルフ", "フォレスティエ", "test", "國府田マリ子", 165);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 48, "天真爛漫で人気者のカリスマモデル", 101601, "ファッション", "スズナ", 4, 14, 17, "O", 0, "魔族", "ルーセント学院", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "上坂すみれ", 167);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 53, "いつでも「なんくるないさ～」な天然娘", 101701, "踊り、空手", "カオリ", 7, 10, 17, "A", 0, "獣人族", "自警団（カォン）", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "高森奈津美", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (14, 52, "多くの男性を魅了する無垢な女教師", 101801, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "イオ", 8, 14, 23, "B", 0, "魔族", "ルーセント学院", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "伊藤静", 162);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 21, "お歌もにんじんも、ウサギさんも大好き♪", 102001, "かわいいもの集め", "ミミ", 4, 5, 10, "O", 0, "獣人族", "リトルリリカル", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "日高里菜", 117);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, 40, "泣き虫で臆病な守ってあげたい女の子", 102101, "観劇、おままごと", "クルミ", 6, 9, 12, "B", 0, "ヒューマン", "サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "植田佳奈", 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 40, "人見知りであまのじゃくな女の子", 102201, "ゲーム全般", "ヨリ", 11, 7, 13, "O", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "原紗友里", 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 38, "ぷうきちといつも一緒！", 102301, "屋内でできる遊び", "アヤネ", 5, 9, 14, "B", 0, "ヒューマン", "サレンディア救護院", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "芹澤優", 148);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 43, "お嬢さまのためにがんばるドジっ娘メイド", 102501, "ご奉仕", "スズメ", 12, 9, 15, "O", 0, "ヒューマン", "サレンディア救護院", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "悠木碧", 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 42, "遊びと睡眠が何より大事なぐうたら娘", 102601, "あんパン", "リン", 1, 11, 17, "B", 0, "獣人族", "牧場（エリザベスパーク）", "test", "小岩井ことり", 144);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (30, 43, "運命の相手に一途すぎる乙女", 102701, "実験、裁縫、料理", "エリコ", 7, 13, 16, "B", 0, "魔族", "トワイライトキャラバン", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "橋本ちなみ", 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, 43, "救護院を経営する優しい庶民派お嬢様", 102801, "経営、お茶会", "サレン", 10, 9, 17, "A", 0, "エルフ", "サレンディア救護院", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "堀江由衣", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 40, "歌って踊れる大人気アイドル", 102901, "舞台鑑賞、ダンス", "ノゾミ", 1, 4, 17, "B", 0, "ヒューマン", "カルミナ", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", "日笠陽子", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (31, 51, "トーゴクの神秘、オシエテクダサイ！", 103001, "忍法開発", "ニノン", 8, 15, 16, "O", 0, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "佐藤聡美", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 42, "占いが得意な霊能少女", 103101, "占い", "シノブ", 12, 7, 18, "AB", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "大坪由佳", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 45, "一人前の商人を目指すパワフルお嬢様", 103201, "慈善事業", "アキノ", 3, 12, 18, "AB", 0, "ヒューマン", "メルクリウス財団", "この私とともにいる限り、\nお金に不自由はさせませんわ！", "松嵜麗", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 35, "みんなを笑顔にするお笑い牧場主", 103301, "漫才", "マヒル", 3, 11, 20, "B", 0, "ヒューマン", "牧場（エリザベスパーク）", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "新田恵海", 142);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (16, 55, "純情でほっとけない大人の女性", 103401, "ウインドーショッピング", "ユカリ", 3, 12, 22, "A", 0, "エルフ", "メルクリウス財団", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "今井麻美", 164);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, 21, "礼儀正しくしっかり者のちびっ子優等生", 103601, "お勉強", "キョウカ", 2, 5, 8, "A", 0, "エルフ", "リトルリリカル", "test", "小倉唯", 118);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 43, "義理堅くてからかい好きな剣術少女", 103701, "剣術、年長者をからかう", "トモ", 8, 8, 13, "A", 0, "ヒューマン", "王宮騎士団（NIGHTMARE）", "test", "茅原実里", 149);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 40, "読書が趣味の病弱少女", 103801, "読書、お散歩", "シオリ", 11, 11, 14, "A", 0, "獣人族", "牧場（エリザベスパーク）", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "小清水亜美", 153);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, 44, "「友達」に憧れる、エルフの森の女の子", 104001, "友達作りのイメトレ", "アオイ", 6, 6, 13, "AB", 0, "エルフ", "フォレスティエ", "友達ができるその日まで…\nBB団で\nトレーニングですっ！", "花澤香菜", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 46, "人々を守るために歌う、唱喚士の少女", 104201, "各種楽器", "チカ", 6, 4, 17, "O", 0, "ヒューマン", "カルミナ", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "福原綾香", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, 54, "男勝りで情に厚いワイルド娘", 104301, "お菓子作り", "マコト", 8, 10, 17, "O", 0, "獣人族", "自警団（カォン）", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "小松未可子", 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 50, "かつては夜を支配した最強の吸血鬼", 104401, "世界征服", "イリヤ", 5, 7, "??", "A", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "test", "丹下桜", 172);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (19, 49, "妄想大好き！　ほんとは照れ屋な女の子", 104501, "小説を読むこと", "クウカ", 11, 15, 18, "AB", 0, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "長妻樹里", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 48, "弱きを助け強きをくじく猫娘", 104601, "猫とたわむれること", "タマキ", 3, 12, 19, "AB", 0, "獣人族", "メルクリウス財団", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "沼倉愛美", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, 50, "素顔を見せない冷静沈着な女性騎士", 104701, "格闘技、湯浴み", "ジュン", 10, 8, 25, "A", 0, "ヒューマン", "王宮騎士団（NIGHTMARE）", "？？？", "川澄綾子", 171);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 49, "仕事も私事も効率優先な傭兵少女", 104801, "傭兵などのアルバイト", "ミフユ", 11, 12, 20, "O", 0, "ヒューマン", "メルクリウス財団", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "田所あずさ", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 54, "お姉ちゃんがお世話してあげるからねっ！", 104901, "家事全般", "シズル", 10, 3, 18, "O", 0, "ヒューマン", "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "生天目仁美", 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 22, "ちょっとおませな恋に恋する女の子", 105001, "ファッション誌鑑賞、コスメ集め", "ミサキ", 1, 14, 11, "A", 0, "魔族", "ルーセント学院", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "久野美咲", 120);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 53, "実験が趣味の危険な科学者", 105101, "研究、実験", "ミツキ", 3, 13, 27, "A", 0, "ヒューマン", "トワイライトキャラバン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "三石琴乃", 166);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (14, 100, "乙女チックなもふもふアニマル", 105201, "毛繕い、お喋り", "リマ", 3, 11, 17, "A", 0, "獣人族", "牧場（エリザベスパーク）", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "徳井青空", 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (28, 33, "見た目も中身もお子ちゃまな異国の軍人", 105301, "お菓子屋通い", "モニカ", 7, 15, 17, "A", 0, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "辻あゆみ", 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 45, "ファッション大好きなキュートガール", 105401, "裁縫", "ツムギ", 9, 4, 14, "AB", 0, "ヒューマン", "カルミナ", "test", "木戸衣吹", 153);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 43, "どこまでも一途に慕う、純情乙女", 105501, "観察", "アユミ", 4, 15, 16, "O", 0, "エルフ", "ヴァイスフリューゲル　ランドソル支部", "test", "大関英里", 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 54, "人情味溢れる粋でいなせな「姉御」", 105601, "釣り", "ルカ", 7, 13, 25, "B", 0, "ヒューマン", "トワイライトキャラバン", "test", "佐藤利奈", 167);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 45, "空への冒険を夢見る騎空士の少女", 105701, "冒険、おしゃべり", "ジータ", 3, "", 17, "O", 0, "ヒューマン", "？？？", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", "金元寿子", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (31, 46, "いつも元気な腹ペコ少女", 105801, "食べ歩き、料理", "ペコリーヌ", 3, 1, 17, "O", 0, "ヒューマン", "美食殿", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "M・A・O", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 35, "主を慕う、小さなガイド役", 105901, "瞑想、動植物の飼育", "コッコロ", 5, 1, 11, "B", 0, "エルフ", "美食殿", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "伊藤美来", 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, 39, "行き倒れの謎のネコミミ魔法使い", 106001, "猫と遊ぶ", "キャル", 9, 1, 14, "A", 0, "獣人族", "美食殿", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "立花理香", 152);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 40, "さまよえる謎の少女", 106101, "冒険、思い出話", "ムイミ", 8, "", 16, "O", 0, "ヒューマン", "？？？", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "潘めぐみ", 148);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (17, 42, "森番を目指すエルフの少女", 106301, "キレイな葉っぱを集めること", "アリサ", 6, "", 15, "O", 0, "エルフ", "？？？", "", "優木かな", 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (14, "???", "記憶喪失のドラゴン娘", 106401, "読書、ストレッチ", "シェフィ", 12, 1, 14, "B", 0, "ドラゴン族", "美食殿", "", "近藤玲奈", 147);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, "???", "拳で語る喧嘩屋ドラゴン少女", 106501, "格闘技", "カヤ", 6, 17, 16, "B", 0, "ドラゴン族", "ドラゴンズネスト", "", "小市眞琴", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (29, "???", "口が達者なヘタレドラゴン", 106601, "ゲーム", "イノリ", 9, 17, 13, "AB", 0, "ドラゴン族", "ドラゴンズネスト", "", "藤田茜", 145);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (17, "???", "妖しい微笑で全てを見透かす臥竜の頭領", 106701, "絵画、読書", "ホマレ", 4, 17, 25, "O", 0, "ドラゴン族", "ドラゴンズネスト", "", "大西沙織", 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, "??", "秘密結社ラビリンスの『迷宮女王』", 106801, "人間観察", "ラビリスタ", 7, 3, 25, "AB", 0, "ヒューマン", "ラビリンス", "", "沢城みゆき", 160);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, "??", "謎に包まれたランドソルの主", 106901, "占い、支配", "カイザーインサイト", 7, "", 29, "AB", 0, "獣人族", "？？？", "", "蒼井翔太", 166);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, "??", "研究所に隠れ住む物静かなお姉さん", 107001, "物真似、芸術鑑賞", "ネネカ", 3, "", 24, "O", 0, "エルフ", "？？？", "", "井口裕香", 149);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, "??", "傍若無人な王宮騎士団副団長", 107101, "強敵との闘争", "クリスティーナ", 2, 8, 27, "O", 0, "ヒューマン", "王宮騎士団（NIGHTMARE）", "", "たかはし智秋", 165);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (31, 46, "いつも元気な腹ペコ少女", 107501, "食べ歩き、料理", "ペコリーヌ（サマー）", 3, 1, 17, "O", 0, "ヒューマン", "美食殿", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "M・A・O", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 35, "主を慕う、小さなガイド役", 107601, "瞑想、動植物の飼育", "コッコロ（サマー）", 5, 1, 11, "B", 0, "エルフ", "美食殿", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "伊藤美来", 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 43, "お嬢さまのためにがんばるドジっ娘メイド", 107701, "ご奉仕", "スズメ（サマー）", 12, 9, 15, "O", 0, "ヒューマン", "サレンディア救護院", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "悠木碧", 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, 39, "行き倒れの謎のネコミミ魔法使い", 107801, "猫と遊ぶ", "キャル（サマー）", 9, 1, 14, "A", 0, "獣人族", "美食殿", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "立花理香", 152);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 48, "弱きを助け強きをくじく猫娘", 107901, "猫とたわむれること", "タマキ（サマー）", 3, 12, 19, "AB", 0, "獣人族", "メルクリウス財団", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "沼倉愛美", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 49, "仕事も私事も効率優先な傭兵少女", 108001, "傭兵などのアルバイト", "ミフユ（サマー）", 11, 12, 20, "O", 0, "ヒューマン", "メルクリウス財団", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "田所あずさ", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 42, "占いが得意な霊能少女", 108101, "占い", "シノブ（ハロウィン）", 12, 7, 18, "AB", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "大坪由佳", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (23, 32, "プリン大好きゴースト娘", 108201, "プリンを食べること", "ミヤコ（ハロウィン）", 1, 7, 14, "B", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "雨宮天", 130);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 22, "ちょっとおませな恋に恋する女の子", 108301, "ファッション誌鑑賞、コスメ集め", "ミサキ（ハロウィン）", 1, 14, 11, "A", 0, "魔族", "ルーセント学院", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "久野美咲", 120);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 46, "人々を守るために歌う、唱喚士の少女", 108401, "各種楽器", "チカ（クリスマス）", 6, 4, 17, "O", 0, "ヒューマン", "カルミナ", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "福原綾香", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, 40, "泣き虫で臆病な守ってあげたい女の子", 108501, "観劇、おままごと", "クルミ（クリスマス）", 6, 9, 12, "B", 0, "ヒューマン", "サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "植田佳奈", 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 38, "ぷうきちといつも一緒！", 108601, "屋内でできる遊び", "アヤネ（クリスマス）", 5, 9, 14, "B", 0, "ヒューマン", "サレンディア救護院", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "芹澤優", 148);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (27, 44, "人助けが大好き！　前向き格闘娘", 108701, "人助け、応援", "ヒヨリ（ニューイヤー）", 8, 2, 16, "A", 0, "獣人族", "トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "東山奈央", 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 47, "戦闘のサポートが得意な、心優しい少女", 108801, "料理、人間観察", "ユイ（ニューイヤー）", 4, 2, 17, "O", 0, "ヒューマン", "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "種田梨沙", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 46, "クールで何事にも真っ直ぐな剣士", 108901, "読書、乗馬、お茶", "レイ（ニューイヤー）", 1, 2, 18, "B", 0, "魔族", "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "早見沙織", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (30, 43, "運命の相手に一途すぎる乙女", 109001, "実験、裁縫、料理", "エリコ（バレンタイン）", 7, 13, 16, "B", 0, "魔族", "トワイライトキャラバン", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "橋本ちなみ", 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 54, "お姉ちゃんがお世話してあげるからねっ！", 109101, "家事全般", "シズル（バレンタイン）", 10, 3, 18, "O", 0, "ヒューマン", "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "生天目仁美", 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 55, "英霊と契約を結んだマナリアの天才王女", 109201, "読書", "アン", 12, "", 17, "AB", 0, "ヒューマン", "？？？", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "日笠陽子", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, 45, "マナリア魔法学院の新入生", 109301, "食べること、眠ること", "ルゥ", 2, "", 16, "O", 0, "ヒューマン", "？？？", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "こやまきみこ", 144);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 67, "人を超越した力を有す心優しい竜姫", 109401, "ピアノ", "グレア", 11, "", 17, "B", 0, "半人半竜", "？？？", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "福原綾香", 167);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (19, 49, "妄想大好き！　ほんとは照れ屋な女の子", 109501, "小説を読むこと", "クウカ（オーエド）", 11, 15, 18, "AB", 0, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "長妻樹里", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (31, 51, "トーゴクの神秘、オシエテクダサイ！", 109601, "忍法開発", "ニノン（オーエド）", 8, 15, 16, "O", 0, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "佐藤聡美", 163);
