INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 35, "主を慕う、小さなガイド役", 111901, "瞑想、動植物の飼育", "コッコロ（ニューイヤー）", 5, 1, 11, "B", 0, "エルフ", "美食殿", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "伊藤美来", 140);
