INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 35, "みんなを笑顔にするお笑い牧場主", 112801, "漫才", "マヒル（レンジャー）", 3, 11, 20, "B", 0, "ヒューマン", "牧場（エリザベスパーク）", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "新田恵海", 142);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, 44, "人懐っこくてマシンガントークな妹系少女", 112901, "お裁縫", "リノ（ワンダー）", 8, 3, 15, "A", 0, "ヒューマン", "ラビリンス", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "阿澄佳奈", 156);
