INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 45, "前世を信じる中二病患者、「疾風の冥姫」", 113201, "小説執筆", "アンナ（サマー）", 7, 13, 17, "A", 0, "魔族", "トワイライトキャラバン", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "髙野麻美", 159);
