INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 46, "クールで何事にも真っ直ぐな剣士", 114001, "読書、乗馬、お茶", "レイ（ハロウィン）", 1, 2, 18, "B", 0, "魔族", "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "早見沙織", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, 40, "ヒーローに憧れる騎士見習いの少女", 114101, "ヒーローごっこ", "マツリ（ハロウィン）", 11, 8, 12, "O", 0, "獣人族", "王宮騎士団（NIGHTMARE）", "", "下田麻美", 146);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (28, 33, "見た目も中身もお子ちゃまな異国の軍人", 114201, "お菓子屋通い", "モニカ（マジカル）", 7, 15, 17, "A", 0, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "辻あゆみ", 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 43, "義理堅くてからかい好きな剣術少女", 114301, "剣術、年長者をからかう", "トモ（マジカル）", 8, 8, 13, "A", 0, "ヒューマン", "王宮騎士団（NIGHTMARE）", "", "茅原実里", 149);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 45, "一人前の商人を目指すパワフルお嬢様", 114401, "慈善事業", "アキノ（クリスマス）", 3, 12, 18, "AB", 0, "ヒューマン", "メルクリウス財団", "この私とともにいる限り、\nお金に不自由はさせませんわ！", "松嵜麗", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, 43, "救護院を経営する優しい庶民派お嬢様", 114501, "経営、お茶会", "サレン（クリスマス）", 10, 9, 17, "A", 0, "エルフ", "サレンディア救護院", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "堀江由衣", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (16, 55, "純情でほっとけない大人の女性", 114601, "ウインドーショッピング", "ユカリ（クリスマス）", 3, 12, 22, "A", 0, "エルフ", "メルクリウス財団", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "今井麻美", 164);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 40, "さまよえる謎の少女", 114701, "冒険、思い出話", "ムイミ（ニューイヤー）", 8, "", 16, "O", 0, "ヒューマン", "？？？", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "潘めぐみ", 148);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, "??", "研究所に隠れ住む物静かなお姉さん", 115001, "物真似、芸術鑑賞", "ネネカ（ニューイヤー）", 3, "", 24, "O", 0, "エルフ", "？？？", "", "井口裕香", 149);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 35, "主を慕う、小さなガイド役", 115501, "瞑想、動植物の飼育", "コッコロ（儀装束）", 5, 1, 11, "B", 0, "エルフ", "美食殿", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "伊藤美来", 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 47, "戦闘のサポートが得意な、心優しい少女", 115601, "料理、人間観察", "ユイ（儀装束）", 4, 2, 17, "O", 0, "ヒューマン", "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "種田梨沙", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 41, "頭脳明晰な美少女名探偵", 115701, "読書、推理", "カスミ（サマー）", 11, 10, 15, "AB", 0, "獣人族", "自警団（カォン）", "", "水瀬いのり", 152);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (14, 100, "乙女チックなもふもふアニマル", 115801, "毛繕い、お喋り", "リマ（シンデレラ）", 3, 11, 17, "A", 0, "獣人族", "牧場（エリザベスパーク）", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "徳井青空", 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, 54, "男勝りで情に厚いワイルド娘", 115901, "お菓子作り", "マコト（シンデレラ）", 8, 10, 17, "O", 0, "獣人族", "自警団（カォン）", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "小松未可子", 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 42, "マホマホ王国のプリンセス", 116001, "空想、ぬいぐるみ集め", "マホ（シンデレラ）", 9, 10, 16, "O", 0, "獣人族", "自警団（カォン）", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "内田真礼", 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 42, "ダウンタウン育ちのダウナー系エルフ", 116201, "ダーツ", "クロエ（聖学祭）", 8, 16, 17, "O", 0, "エルフ", "聖テレサ女学院（なかよし部）", "", "種﨑敦美", 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (15, 46, "自由奔放ナチュラル無礼な現代っ子", 116301, "ダンス、カラオケ", "チエル（聖学祭）", 9, 16, 16, "O", 0, "ヒューマン", "聖テレサ女学院（なかよし部）", "", "佐倉綾音", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (28, 36, "書庫に眠れる小さな賢人", 116401, "読書", "ユニ（聖学祭）", 2, 16, 18, "O", 0, "ヒューマン", "聖テレサ女学院（なかよし部）", "", "小原好美", 142);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (29, "???", "口が達者なヘタレドラゴン", 116501, "ゲーム", "イノリ（タイムトラベル）", 9, 17, 13, "AB", 0, "ドラゴン族", "ドラゴンズネスト", "", "藤田茜", 145);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, "???", "拳で語る喧嘩屋ドラゴン少女", 116601, "格闘技", "カヤ（タイムトラベル）", 6, 17, 16, "B", 0, "ドラゴン族", "ドラゴンズネスト", "", "小市眞琴", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, 44, "「友達」に憧れる、エルフの森の女の子", 116701, "友達作りのイメトレ", "アオイ（作業服）", 6, 6, 13, "AB", 0, "エルフ", "フォレスティエ", "", "花澤香菜", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 48, "弱きを助け強きをくじく猫娘", 116801, "猫とたわむれること", "タマキ（作業服）", 3, 12, 19, "AB", 0, "獣人族", "メルクリウス財団", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "沼倉愛美", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 49, "仕事も私事も効率優先な傭兵少女", 116901, "傭兵などのアルバイト", "ミフユ（作業服）", 11, 12, 20, "O", 0, "ヒューマン", "メルクリウス財団", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "田所あずさ", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (30, 43, "運命の相手に一途すぎる乙女", 117001, "実験、裁縫、料理", "エリコ（サマー）", 7, 13, 16, "B", 0, "魔族", "トワイライトキャラバン", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "橋本ちなみ", 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 54, "お姉ちゃんがお世話してあげるからねっ！", 117101, "家事全般", "シズル（サマー）", 10, 3, 18, "O", 0, "ヒューマン", "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "生天目仁美", 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 40, "歌って踊れる大人気アイドル", 117201, "舞台鑑賞、ダンス", "ノゾミ（サマー）", 1, 4, 17, "B", 0, "ヒューマン", "カルミナ", "", "日笠陽子", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 46, "人々を守るために歌う、唱喚士の少女", 117301, "各種楽器", "チカ（サマー）", 6, 4, 17, "O", 0, "ヒューマン", "カルミナ", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "福原綾香", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 45, "ファッション大好きなキュートガール", 117401, "裁縫", "ツムギ（サマー）", 9, 4, 14, "AB", 0, "ヒューマン", "カルミナ", "", "木戸衣吹", 153);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 53, "実験が趣味の危険な科学者", 117501, "研究、実験", "ミツキ（オーエド）", 3, 13, 27, "A", 0, "ヒューマン", "トワイライトキャラバン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "三石琴乃", 166);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 40, "ボクは誰よりも美しい", 117601, "鏡で自分を見ること", "ユキ（オーエド）", 10, 15, 14, "AB", 0, "エルフ", "ヴァイスフリューゲル　ランドソル支部", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "大空直美", 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 53, "いつでも「なんくるないさ～」な天然娘", 117701, "踊り、空手", "カオリ（ハロウィン）", 7, 10, 17, "A", 0, "獣人族", "自警団（カォン）", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "高森奈津美", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (31, 51, "トーゴクの神秘、オシエテクダサイ！", 117801, "忍法開発", "ニノン（ハロウィン）", 8, 15, 16, "O", 0, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "佐藤聡美", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 48, "天真爛漫で人気者のカリスマモデル", 117901, "ファッション", "スズナ（ハロウィン）", 4, 14, 17, "O", 0, "魔族", "ルーセント学院", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "上坂すみれ", 167);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (19, 57, "忠義に目覚めた女商人", 118001, "お金を数えること、悪だくみ", "クレジッタ", 9, 18, 26, "A", 0, "ヒューマン", "リッチモンド商工会", "", "Lynn", 160);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (28, 53, "静寂を求め歌う陰気少女", 118101, "歌、読書、詩を書くこと", "ランファ", 12, 19, 20, "O", 0, "魔族", "レイジ・レギオン", "", "原田彩楓", 165);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, "??", "明朗快活、なれど破滅に流るる溌溂少女", 118201, "特に無し", "ミソラ", 7, 19, 16, "A", 0, "ヒューマン", "レイジ・レギオン", "", "鬼頭明里", 159);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 43, "【ギルド管理協会】職員の親切なお姉さん", 118501, "書類仕事、散歩、ボードゲーム", "カリン", 9, "", 24, "A", 0, "ヒューマン", "？？？", "", "洲崎綾", 152);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("?", "???", "幻霧に戯れる悪戯好きなガイド妖精", 118601, "悪戯をすること", "ネビア", "?", "", "??", "?", 0, "？？？", "？？？", "", "相坂優歌", "???");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (14, 52, "多くの男性を魅了する無垢な女教師", 119001, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "イオ（ノワール）", 8, 14, 23, "B", 0, "魔族", "ルーセント学院", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "伊藤静", 162);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (19, 49, "妄想大好き！　ほんとは照れ屋な女の子", 119101, "小説を読むこと", "クウカ（ノワール）", 11, 15, 18, "AB", 0, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "長妻樹里", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 35, "みんなを笑顔にするお笑い牧場主", 119201, "漫才", "マヒル（クリスマス）", 3, 11, 20, "B", 0, "ヒューマン", "牧場（エリザベスパーク）", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "新田恵海", 142);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, 44, "人懐っこくてマシンガントークな妹系少女", 119301, "お裁縫", "リノ（クリスマス）", 8, 3, 15, "A", 0, "ヒューマン", "ラビリンス", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "阿澄佳奈", 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (23, 32, "プリン大好きゴースト娘", 119901, "プリンを食べること", "ミヤコ（クリスマス）", 1, 7, 14, "B", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "雨宮天", 130);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 54, "お姉ちゃんがお世話してあげるからねっ！", 120001, "家事全般", "シズル（ノワール）", 10, 3, 18, "O", 0, "ヒューマン", "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "生天目仁美", 168);
