INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, 40, "泣き虫で臆病な守ってあげたい女の子", 121301, "観劇、おままごと", "クルミ（ステージ）", 6, 9, 12, "B", 0, "ヒューマン", "サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "植田佳奈", 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 22, "ちょっとおませな恋に恋する女の子", 121401, "ファッション誌鑑賞、コスメ集め", "ミサキ（ステージ）", 1, 14, 11, "A", 0, "魔族", "ルーセント学院", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "久野美咲", 120);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 43, "どこまでも一途に慕う、純情乙女", 121501, "観察", "アユミ（怪盗）", 4, 15, 16, "O", 0, "エルフ", "ヴァイスフリューゲル　ランドソル支部", "", "大関英里", 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (29, "???", "口が達者なヘタレドラゴン", 121601, "ゲーム", "イノリ（怪盗）", 9, 17, 13, "AB", 0, "ドラゴン族", "ドラゴンズネスト", "", "藤田茜", 145);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 45, "前世を信じる中二病患者、「疾風の冥姫」", 121901, "小説執筆", "アンナ（パイレーツ）", 7, 13, 17, "A", 0, "魔族", "トワイライトキャラバン", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "髙野麻美", 159);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 42, "占いが得意な霊能少女", 122001, "占い", "シノブ（パイレーツ）", 12, 7, 18, "AB", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "大坪由佳", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, 44, "「友達」に憧れる、エルフの森の女の子", 122101, "友達作りのイメトレ", "アオイ（キャンプ）", 6, 6, 13, "AB", 0, "エルフ", "フォレスティエ", "", "花澤香菜", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (16, 55, "純情でほっとけない大人の女性", 122201, "ウインドーショッピング", "ユカリ（キャンプ）", 3, 12, 22, "A", 0, "エルフ", "メルクリウス財団", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "今井麻美", 164);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, 41, "けんぞくのご主人様", 122301, "お散歩、お料理", "ヴァンピィ", 12, "", "??", "AB", 0, "魔族", "？？？", "", "釘宮理恵", 149);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (27, 44, "人助けが大好き！　前向き格闘娘", 122401, "人助け、応援", "ヒヨリ（サマー）", 8, 2, 16, "A", 0, "獣人族", "トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "東山奈央", 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 46, "クールで何事にも真っ直ぐな剣士", 122501, "読書、乗馬、お茶", "レイ（サマー）", 1, 2, 18, "B", 0, "魔族", "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "早見沙織", 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 47, "戦闘のサポートが得意な、心優しい少女", 122601, "料理、人間観察", "ユイ（サマー）", 4, 2, 17, "O", 0, "ヒューマン", "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "種田梨沙", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, 21, "礼儀正しくしっかり者のちびっ子優等生", 122701, "お勉強", "キョウカ（サマー）", 2, 5, 8, "A", 0, "エルフ", "リトルリリカル", "", "小倉唯", 118);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 27, "探検好きのイタズラっ子", 122801, "いたずら、探検", "ミソギ（サマー）", 8, 5, 9, "O", 0, "ヒューマン", "リトルリリカル", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "諸星すみれ", 128);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 21, "お歌もにんじんも、ウサギさんも大好き♪", 122901, "かわいいもの集め", "ミミ（サマー）", 4, 5, 10, "O", 0, "獣人族", "リトルリリカル", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "日高里菜", 117);
