INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 42, "マホマホ王国のプリンセス", 123101, "空想、ぬいぐるみ集め", "マホ（エクスプローラー）", 9, 10, 16, "O", 0, "獣人族", "自警団（カォン）", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "内田真礼", 155);
