INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 42, "甘え上手なみんなの人気者", 124001, "サックス", "アカリ（クリスマス）", 11, 7, 13, "O", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "浅倉杏美", 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 40, "人見知りであまのじゃくな女の子", 124101, "ゲーム全般", "ヨリ（クリスマス）", 11, 7, 13, "O", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "原紗友里", 150);
