INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 40, "さまよえる謎の少女", 125001, "冒険、思い出話", "ムイミ（リベレイター）", 8, "", 16, "O", 0, "ヒューマン", "？？？", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "潘めぐみ", 148);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 48, "弱きを助け強きをくじく猫娘", 125101, "猫とたわむれること", "タマキ（カフェ）", 3, 12, 19, "AB", 0, "獣人族", "メルクリウス財団", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "沼倉愛美", 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (28, 33, "見た目も中身もお子ちゃまな異国の軍人", 125201, "お菓子屋通い", "モニカ（カフェ）", 7, 15, 17, "A", 0, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "辻あゆみ", 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 35, "主を慕う、小さなガイド役", 125301, "瞑想、動植物の飼育", "コッコロ（レンジャー）", 5, 1, 11, "B", 0, "エルフ", "美食殿", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "伊藤美来", 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 40, "読書が趣味の病弱少女", 125401, "読書、お散歩", "シオリ（レンジャー）", 11, 11, 14, "A", 0, "獣人族", "牧場（エリザベスパーク）", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "小清水亜美", 153);
