INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (19, 49, "妄想大好き！　ほんとは照れ屋な女の子", 127001, "小説を読むこと", "クウカ（サマー）", 11, 15, 18, "AB", 0, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "長妻樹里", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 42, "占いが得意な霊能少女", 127101, "占い", "シノブ（サマー）", 12, 7, 18, "AB", 0, "魔族", "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "大坪由佳", 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, 39, "行き倒れの謎のネコミミ魔法使い", 127201, "猫と遊ぶ", "キャル（編入生）", 9, 1, 14, "A", 0, "獣人族", "美食殿", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "立花理香", 152);
